List<AdminProgressBatch> _mergeWorkerWipBatches(
  Iterable<AdminProgressBatch> progressBatches,
  Iterable<AdminProgressBatch> openingWipBatches,
) {
  final byBatchId = <String, AdminProgressBatch>{};
  for (final batch in progressBatches) {
    byBatchId[batch.batchId.trim()] = batch;
  }
  for (final batch in openingWipBatches) {
    byBatchId.putIfAbsent(batch.batchId.trim(), () => batch);
  }
  final merged = byBatchId.values.toList(growable: false);
  merged.sort((left, right) {
    final leftAt = left.completedAtUnix > left.startedAtUnix
        ? left.completedAtUnix
        : left.startedAtUnix;
    final rightAt = right.completedAtUnix > right.startedAtUnix
        ? right.completedAtUnix
        : right.startedAtUnix;
    final byTime = rightAt.compareTo(leftAt);
    return byTime != 0 ? byTime : right.batchId.compareTo(left.batchId);
  });
  return merged;
}

List<RpsQrDetail> _workerWipReprintDetails(
  AdminProgressBatch batch,
  AppLocalizations l10n,
  List<AdminApparatus> apparatusCatalog,
) {
  final current = canonicalApparatusDisplayLabel(
    _workerWipFirstNotEmpty([
      batch.currentLocation,
      batch.currentApparatus,
      batch.apparatus,
    ]),
    apparatusCatalog,
  );
  final worker = _workerWipFirstNotEmpty([
    batch.workerDisplayName,
    batch.executorName,
    batch.workerRef,
  ]);
  final next = canonicalApparatusDisplayLabel(
    batch.nextApparatus,
    apparatusCatalog,
  );
  final action = _workerWipActionLabel(batch.action, l10n);
  return [
    if (batch.orderId.trim().isNotEmpty)
      RpsQrDetail(
        l10n.productionText('worker.daily.order'),
        batch.orderId.trim(),
      ),
    if (batch.batchId.trim().isNotEmpty)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.id'),
        batch.batchId.trim(),
      ),
    RpsQrDetail(
      l10n.productionText('worker.wip.info.quantity'),
      formatQuantityWithUnit(
        batch.producedQty,
        batch.uom,
        trimTrailingZeros: true,
      ),
    ),
    RpsQrDetail(
      l10n.productionText('worker.daily.status'),
      _workerWipStatusLabel(batch, l10n),
    ),
    if (batch.startedAtUnix > 0)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.started'),
        formatUnixSecondsLocalDateTime(batch.startedAtUnix),
      ),
    if (batch.completedAtUnix > 0)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.finished'),
        formatUnixSecondsLocalDateTime(batch.completedAtUnix),
      ),
    RpsQrDetail(
      l10n.productionText('worker.wip.info.source'),
      canonicalApparatusDisplayLabel(
        _workerWipValue(batch.apparatus),
        apparatusCatalog,
      ),
    ),
    if (action.isNotEmpty)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.action'),
        action,
      ),
    RpsQrDetail(
      l10n.productionText('worker.wip.info.location'),
      current,
    ),
    if (next.trim().isNotEmpty)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.next_machine'),
        next,
      ),
    if (worker.trim().isNotEmpty)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.worker'),
        worker,
      ),
    if (batch.description.trim().isNotEmpty)
      RpsQrDetail(
        l10n.productionText('worker.wip.info.note'),
        batch.description.trim(),
      ),
  ];
}

List<AdminProgressBatch> _openingWipBatchesProducedByApparatus(
  Iterable<AdminOpeningWipRecord> records, {
  required ProductionMapSaved order,
  String apparatusId = '',
}) {
  final normalizedOrderId = order.map.id.trim();
  final normalizedApparatusId = apparatusId.trim();
  final batches = <AdminProgressBatch>[];
  for (final record in records) {
    final intake = record.intake;
    final sourceApparatus = _workerWipFirstNotEmpty([
      intake.sourceApparatus,
      intake.entryApparatus,
    ]);
    if (intake.orderId.trim() != normalizedOrderId ||
        sourceApparatus.isEmpty ||
        (normalizedApparatusId.isNotEmpty &&
            sourceApparatus != normalizedApparatusId)) {
      continue;
    }
    for (final batch in record.batches) {
      final wipStatus = batch.wipStatus.trim().toLowerCase();
      if (wipStatus == 'void') continue;
      final nextApparatus = _openingWipNextApparatus(
        order: order,
        intake: intake,
        batch: batch,
      );
      batches.add(
        _openingWipAsProgressBatch(
          batch,
          sourceApparatus,
          intake: intake,
          nextApparatus: nextApparatus,
        ),
      );
    }
  }
  return batches;
}

String _openingWipNextApparatus({
  required ProductionMapSaved order,
  required AdminOpeningWipIntake intake,
  required AdminOpeningWipBatch batch,
}) {
  final consumedBy = _workerWipFirstNotEmpty([
    batch.usedByApparatus,
    batch.processedByApparatus,
  ]);
  if (consumedBy.isNotEmpty) return consumedBy;
  final nextStages = productionMapNextWorkStagesForNode(
    map: order.map,
    stageNodeId: intake.sourceStageNodeId,
  );
  if (nextStages.length != 1) return '';
  return nextStages.single.apparatusId?.trim() ?? '';
}

List<AdminProgressBatch> _wipBatchesProducedByApparatus(
  Iterable<AdminProgressBatch> batches, {
  required String orderId,
  required String apparatusId,
}) {
  final normalizedOrderId = orderId.trim();
  final normalizedApparatusId = apparatusId.trim();
  if (normalizedOrderId.isEmpty || normalizedApparatusId.isEmpty) {
    return const <AdminProgressBatch>[];
  }
  return [
    for (final batch in batches)
      if (batch.orderId.trim() == normalizedOrderId &&
          batch.apparatus.trim() == normalizedApparatusId)
        batch,
  ];
}

class _WorkerWipHistoryList extends StatelessWidget {
  const _WorkerWipHistoryList({
    required this.batches,
    required this.apparatusCatalog,
    required this.onLongPress,
  });

  final List<AdminProgressBatch> batches;
  final List<AdminApparatus> apparatusCatalog;
  final void Function(AdminProgressBatch batch)? onLongPress;

  @override
  Widget build(BuildContext context) {
    final waitingCount = batches
        .where((batch) => _workerWipKind(batch) == _WorkerWipKind.waiting)
        .length;
    final inUseCount = batches
        .where((batch) => _workerWipKind(batch) == _WorkerWipKind.inUse)
        .length;
    final processedCount = batches
        .where((batch) => _workerWipKind(batch) == _WorkerWipKind.processed)
        .length;

    return ListView(
      key: const ValueKey('worker-wip-history-sheet'),
      padding: const EdgeInsets.only(bottom: 8),
      children: [
        _WorkerWipHistorySummary(
          count: batches.length,
          waitingCount: waitingCount,
          inUseCount: inUseCount,
          processedCount: processedCount,
        ),
        const SizedBox(height: 12),
        for (var index = 0; index < batches.length; index++)
          Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: _WorkerWipHistoryCard(
              key: ValueKey('worker-wip-item-$index'),
              batch: batches[index],
              index: index,
              apparatusCatalog: apparatusCatalog,
              onLongPress: onLongPress == null
                  ? null
                  : () => onLongPress!(batches[index]),
            ),
          ),
      ],
    );
  }
}
